#!/usr/bin/env python3
"""Render the PQ2 report from recorded JSON; never enter measurements by hand."""
import argparse
import json
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--raw', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    load = lambda path: json.loads((args.raw / path).read_text())
    meta = load('model/metadata.json')
    lines = ['# M6 PQ2 prefill: Bonsai 2 27B', '',
             'Generated by `tools/report_metal_pq2.py` from the adjacent raw campaign.', '',
             f'Measured revision: `{meta["revision"]}`. Model SHA-256: `{meta["model"]["sha256"]}`.',
             'Binary hashes, temperatures, power state, dispatch counters and every sample are retained.',
             'The measured GPU kernel sources are unchanged in the final implementation. Subsequent host setup selects four SIMD groups as the staged-mode default and serializes native setup/scratch under the existing sequence lock; measurements explicitly select the measured geometry. The clean revision A/B validates the final host code separately.', '',
             '## Scope and safety', '',
             'All candidates are opt-in. The default, exact weights, single-token decode, non-PQ2 formats and unsupported GPUs retain their existing kernels. A failed native compilation or workspace reservation falls back to the existing path.',
             'The original compact PQ2 weights remain unchanged. Full-K candidates temporarily requantize one matrix pair; they do not expand or cache the entire model.', '',
             'Block modes preserve original half scales and exact integer weight codes. Their per-128 preparation/scaling overhead outweighed native matrix throughput in this campaign. Full-K INT8/FP8 use power-of-two row scales, adding weight and activation rounding.', '',
             '## Matrix exploration', '',
             'The existing Metal tensor path reads FP32 activations and stages decoded PQ2 weights as FP16. `half2` instead pairs scaled FP16 activations with original packed INT2 weight codes. The full-K FP8 and INT8 candidates use native low-precision operand tensors.', '',
             'Two forward/reverse rotations explore 65 configurations on three actual Bonsai layer shapes. Timings include preparation, GEMM and synchronization after 64 discarded warmups. Sampled CPU-double dots check an independent quantization oracle. This is tuning data, not a statistical application performance gate.', '',
             '| M × N × K | Existing Metal (µs) | Best INT8 (µs) | Best FP8 (µs) | INT8 speedup |',
             '|---|---:|---:|---:|---:|']
    matrix = load('matrix/summary.json')
    shapes = sorted({(r['m'], r['n'], r['k']) for r in matrix})
    for shape in shapes:
        rows = [r for r in matrix if (r['m'], r['n'], r['k']) == shape]
        base = next(r for r in rows if r['config']['mode'] == 'off')
        best = {mode:min((r for r in rows if r['config']['mode'] == mode),key=lambda r:r['wall_us'])
                for mode in ('staged_int8','staged_fp8')}
        i, f = best['staged_int8'], best['staged_fp8']
        lines.append(f'| {shape[0]} × {shape[1]} × {shape[2]} | {base["wall_us"]:.1f} | {i["wall_us"]:.1f} | {f["wall_us"]:.1f} | {i["speedup"]:.3f}× |')
    lines += ['', '| M × N × K | Best block INT8 µs | Best block FP8 µs | Best INT2 µs | Best FP16/INT2 µs | Best cooperative FP16 µs |', '|---|---:|---:|---:|---:|---:|']
    for shape in shapes:
        rows = [r for r in matrix if (r['m'], r['n'], r['k']) == shape]
        us = [min(r['wall_us'] for r in rows if r['config']['mode'] == mode)
              for mode in ('int8','fp8','int2','half2','coop16')]
        lines.append('| ' + ' × '.join(map(str,shape)) + ' | ' + ' | '.join(f'{v:.1f}' for v in us) + ' |')
    lines += ['', 'The selected full-K geometry is a 128-row tile with four SIMD groups. Use `GEIST_METAL_PQ2_TILE=128 GEIST_METAL_PQ2_SIMDGROUPS=4` with `GEIST_METAL_PQ2_MODE=staged_int8` or `staged_fp8`.', '', '## Full-model performance and memory', '',
              'Six rotated cycles per arm, one identical executable and GGUF, AC power, Low Power Mode off, CPU/GPU start temperatures ≤65 °C. Each process discards a longest-prompt warmup; decode measures 32 tokens. The table gives medians and paired per-cycle speedup ranges, including losses. Native dispatch counters verify that each candidate really ran.', '',
              'The optional 512-row protocol changes the session batch limit for **all** arms, including its baseline; it does not change the library default. Compare within each protocol. RSS on macOS omits private Metal allocations; backend allocated memory is the more relevant memory measure here.', '',
              '| Batch limit | Prompt | Mode | Existing tokens/s | Candidate tokens/s | Paired speedup (range) | Wins | Backend Δ MiB | RSS Δ MiB | Decode ratio |',
              '|---|---:|---|---:|---:|---|---:|---:|---:|---:|']
    for folder, limit in [('model','default'),('model-m512','512')]:
        if not (args.raw / folder / 'summary.json').exists():continue
        for row in load(folder+'/summary.json')['performance']:
            a,b=row['baseline'],row[row['arm']];lo,hi=row['paired_range']
            lines.append(f'| {limit} | {row["seq_len"]} | {row["arm"]} | {a["prefill_tps"]:.2f} | {b["prefill_tps"]:.2f} | {row["paired_speedup"]:.3f}× ({lo:.3f}–{hi:.3f}) | {row["wins"]}/6 | {b["backend_allocated_mb"]-a["backend_allocated_mb"]:+.2f} | {b["rss_mb"]-a["rss_mb"]:+.2f} | {b["decode_tps"]/a["decode_tps"]:.3f}× |')
    lines += ['', 'Scratch has a checked high-water allocation of `(rows + n_out) * (n_in + 4)` bytes and is reused serially across layers. The existing path also reserves unused PQ2 half-activation scratch; native branches skip that reservation. Memory deltas therefore include both effects. No model-size reduction is claimed.', '',
              '## Output quality', '',
              'Twelve fixed, self-authored continuation smoke cases use the GGUF Qwen 3.5 single-turn chat format with thinking disabled and long background prefixes (at least 512 tokens), the same token IDs, teacher-forced continuation log-probabilities and 24 fixed greedy output tokens (including any tokens after EOS). Normalized `GEN` replies use the tool’s own stop handling. Conditional perplexity below is a ratio on these continuations, **not** a standard corpus perplexity or a general quality guarantee. Native preparation dispatches are checked in the quality log.', '',
              '| Mode | Continuation tokens | Mean NLL: existing → candidate | Conditional PPL ratio | Exact 24-token streams | First token matches | EOS-stopped token streams |',
              '|---|---:|---|---:|---:|---:|---:|']
    quality_folder='model-chat' if (args.raw/'model-chat/summary.json').exists() else 'model'
    model = load(quality_folder+'/summary.json')
    quality=[json.loads(line) for line in (args.raw/quality_folder/'quality.jsonl').read_text().splitlines()]
    for row in model['quality']:
        nll=row['mean_nll'];arm=row['arm']
        base={r['case']:r for r in quality if r['arm']=='baseline'}
        visible=sum(r['generated_ids_until_eos']==base[r['case']]['generated_ids_until_eos'] for r in quality if r['arm']==arm)
        lines.append(f'| {arm} | {row["continuation_tokens"]} | {nll["baseline"]:.6f} → {nll[arm]:.6f} | {row["conditional_ppl_ratio"]:.6f} | {row["exact_generations"]}/{row["cases"]} | {row["first_token_matches"]}/{row["cases"]} | {visible}/{row["cases"]} |')
    lines += ['', '| Mode | Logit case | Top-1 same | Top-10 overlap | Centered cosine | Centered RMSE | JS divergence (nats) |', '|---|---|---|---:|---:|---:|---:|']
    for r in model['logits']:
        lines.append(f'| {r["arm"]} | {r["case"]} | {r["top1_same"]} | {r["top10_overlap"]}/10 | {r["centered_cosine"]:.6f} | {r["centered_rmse"]:.6f} | {r["js_nats"]:.6f} |')
    lines += ['', 'Requantization can change generated text; these modes remain experimental and disabled by default. Short prompts can lose performance because preparation is not sufficiently amortized. Decode kernels are unchanged; decode timing differences reflect run noise and potentially different prefill state.', '', '## Isolation and validation', '']
    replay = load(quality_folder+'/final-replay.json')
    lines.append(f'- Final executable: {len(replay["cases"])} baseline/INT8/FP8 full-vocabulary dumps reproduce the measured executable bit for bit after host setup/locking edits.')
    default = load(quality_folder+'/default-isolation.json')
    lines.append(f'- Bonsai default: {len(default["cases"])} long-prompt full-vocabulary dumps are bit-identical to clean main.')
    isolation = load('isolation/results.json')
    for name in sorted({r['model'] for r in isolation}):
        rs=[r for r in isolation if r['model']==name]
        lines.append(f'- `{name}`: {len(rs)} arms (including clean main), bit-identical token IDs and full-vocabulary logits with INT8/FP8 flags enabled or disabled.')
    reports=sorted((args.raw/'revision-ab').glob('*/revision_ab.md'))
    if not reports:raise RuntimeError('missing clean revision A/B report')
    ab=reports[-1].read_text().splitlines()
    lines += ['', 'Clean revision A/B on the same exclusively leased M6 (Qwen 3.5 0.8B Q8, six rotated cycles plus a byte-identical baseline control):', '',
              '| row | variant | baseline ms | variant ms | change | 95 % interval | faster | verdict |',
              '|---|---|---:|---:|---:|---|---:|---|']
    lines += [line for line in ab if line.startswith(('| prefill_ms','| decode_ms')) and ' | new | ' in line]
    lines += ['', next(line for line in ab if line.startswith('Control:')), '',
              'All measured default-path changes are within noise. This local run does not replace the required CI approval/gates.']
    lines += ['', 'See `validation.txt` and the revision A/B report in the raw campaign for local checks. Full CI requires the repository’s human `/ci-ok <HEAD>` approval before agent-authored code executes on runners.', '', '## Reproduction', '', 'Build the release tools and a clean-main `dump_geist_logits` executable (`CLEAN_MAIN_DUMP`), acquire the exclusive M6 host lease, then run:', '', '```sh', 'python3 tools/tune_metal_pq2.py --out RAW/matrix', 'python3 tools/bench_metal_pq2_model.py --model BONSAI.gguf --out RAW/model', 'python3 tools/bench_metal_pq2_model.py --model BONSAI.gguf --out RAW/model-m512 --seq-lens 512,2048 --m-max 512 --skip-quality', 'python3 tools/check_metal_pq2_default.py --binary CLEAN_MAIN_DUMP --model BONSAI.gguf --model-results RAW/model', 'python3 tools/check_metal_pq2_replay.py --model-results RAW/model', 'python3 tools/check_metal_pq2_isolation.py --baseline-binary CLEAN_MAIN_DUMP --model QWEN3_Q8.gguf --model QWEN35_Q8.gguf --model LLAMA_Q4KM.gguf --out RAW/isolation', 'python3 tools/bench_revision_ab.py --rev base=origin/main --rev new=HEAD --gguf QWEN35_Q8.gguf --seq-lens 128,512 --warmup 512 --decode-n 32 --cycles 6 --env GEIST_BENCH_BACKEND=metal --env GEIST_METAL_TENSOR=1 --env GEIST_METAL_PQ2_MODE=off --out-dir RAW/revision-ab', 'python3 tools/report_metal_pq2.py --raw RAW --output benchmark/results/M6_PQ2.md', '```', '']
    args.output.write_text('\n'.join(lines))


if __name__ == '__main__':
    main()
